<?php require __DIR__.'/_init.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM order_files WHERE id=?');$q->execute([$id]);$f=$q->fetch();if(!$f){http_response_code(404);exit('فایل پیدا نشد.');}$path=__DIR__.'/../storage/designs/'.$f['stored_name'];if(!is_file($path)){http_response_code(404);exit('فایل روی سرور موجود نیست.');}header('Content-Type: '.$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode(basename($f['original_name'])).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
